import { Directive, input } from '@angular/core';

/**
 * No global-attribute input and no host directives of its own, which is what
 * CDK's `CdkScrollable` and `CdkDrag` are in 22.2.4: Material extends the one
 * and composes it, and ngwr composes the other.
 */
@Directive({ selector: '[fixtureCdkScrollable]' })
export class FixtureCdkScrollable {
  readonly orientation = input<'vertical' | 'horizontal'>('vertical');
}
